from pathlib import Path
w=Path('.work/vtm')
s=(w/'profile-larger-prefix-loop-v1.py').read_text()
s=s.replace('One device-controlled producer/large-mesher/consumer graph with failures and recovery.','Production exterior proof in a device-controlled thin-hand seed/failure/recovery loop.')
a=s.index('@wp.kernel\ndef produce(');b=s.index('@wp.kernel\ndef save_points(')
s=s[:a]+'from tests.test_proven_mesher import producer\n\n'+s[b:]
s=s.replace('int(r < 4)','int(r < 3)').replace('surface("torus")','surface("thin-hand")').replace('surface_subdivisions=4, crease_subdivisions=4','surface_subdivisions=20, crease_subdivisions=20')
s=s.replace('target = wp.full(1, 4096','target = wp.full(1, 1000').replace('seed = wp.full(1, 2026','seed = wp.full(1, 7').replace('domain, 16384, target_count=target, initial_count=256, seed=seed, quality_rounds=4','domain, 1000, target_count=target, initial_count=256, seed=seed, quality_rounds=4, local_quality_retries=4')
s=s.replace('(5, 10)','(4, 10)').replace('(5, 2)','(4, 2)').replace('(5, 16384)','(4, 1000)').replace('(5, len','(4, len').replace('        16384,','        1000,')
s=s.replace('wp.launch(produce, len(source), inputs=[source, domain.points, phase, target, seed])','wp.launch(producer, 1, inputs=[phase, target, seed])')
s=s.replace('wp.load_module(module="tests.test_vtm_core", device=domain.device)','wp.load_module(module="tests.test_vtm_core", device=domain.device)\nwp.load_module(module="tests.test_proven_mesher", device=domain.device)')
s=s.replace('with wp.ScopedCapture() as capture:', 'stream=wp.Stream(domain.device)\nwp.synchronize_device(domain.device)\nwith wp.ScopedStream(stream),wp.ScopedCapture(stream=stream) as capture:')
s=s.replace('wp.capture_launch(capture.graph)','wp.capture_launch(capture.graph,stream=stream)')
s=s.replace('["valid4096", "deformed8192", "invalid16385", "collapsed_domain", "recovered4096"]','["seed7-proof", "invalid-target0", "seed42-no-proof", "seed7-recovered"]')
s=s.replace('values[:, 0].tolist() == [0, 0, 1, 1, 0] and values[:, 1].tolist() == [1, 1, 0, 0, 1]','values[:, 0].tolist() == [0, 1, 0, 0] and values[:, 1].tolist() == [1, 0, 1, 1]')
s=s.replace('values[:, 2].tolist() == [4096, 8192, 0, 0, 4096]','values[:, 2].tolist() == [1000, 0, 1000, 1000]').replace('values[2:4, 2:]','values[1, 2:]').replace('consumed[2:4]','consumed[1]').replace('consumed[[0, 1, 4]]','consumed[[0, 2, 3]]')
s=s.replace('for i in [0, 1, 4]:','for i in [0, 2, 3]:').replace('    if i == 1:\n        ip[:, 0] *= np.float32(1.125)\n','')
p=w/'profile-exterior-bvh-loop-v1.py';assert not p.exists();p.write_text(s)
s=(w/'run-larger-prefix-native-v1.py').read_text()
s=s.replace("import argparse\np=argparse.ArgumentParser();p.add_argument('--loop',action='store_true');a=p.parse_args()\n",'')
s=s.replace("label='larger-prefix-'+('loop' if a.loop else 'full')+'-native-v1'","label='exterior-bvh-loop-native-v1'")
s=s.replace("str(w/('profile-larger-prefix-loop-v1.py' if a.loop else 'profile-larger-prefix-production-v1.py'))","str(w/'profile-exterior-bvh-loop-v1.py')")
s=s.replace('Larger active-prefix routing full or changing-target loop; profiling only','Hierarchical exterior proof in a production thin-hand seed/failure/recovery loop; profiling only')
p=w/'run-exterior-bvh-loop-native-v1.py';assert not p.exists();p.write_text(s)
s=(w/'check-larger-prefix-native-loop-v1.py').read_text().replace('larger-prefix','exterior-bvh')
s=s.replace('[0,0,1,1,0]','[0,1,0,0]').replace('[1,1,0,0,1]','[1,0,1,1]').replace('for i in [2,3]','for i in [1]').replace('for i in [0,1,4]','for i in [0,2,3]').replace('frame4.npz','frame3.npz')
p=w/'check-exterior-bvh-native-loop-v1.py';assert not p.exists();p.write_text(s)
